package com.zhitu.controller;
import com.zhitu.common.ApiResponse;import com.zhitu.dto.Requests;import com.zhitu.service.MatchingService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/matches") public class MatchController {private final MatchingService service;public MatchController(MatchingService s){service=s;}@PostMapping("/analyze")public ApiResponse<Map<String,Object>>analyze(@Valid @RequestBody Requests.MatchRequest r){return ApiResponse.ok("匹配诊断完成",service.analyze(r.resumeId(),r.roleId()));}@GetMapping("/{id}")public ApiResponse<Map<String,Object>>report(@PathVariable long id){return ApiResponse.ok(service.report(id));}@GetMapping public ApiResponse<List<Map<String,Object>>>reports(){return ApiResponse.ok(service.reports());}}
